/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
import collections
import json
import subprocess

candidate = \"ccf27017c973a5359b2f7d0accfbb78851e43b32\"
base = \"23f5fea\"
r3 = \"4ddbd1f\"

def changed(a, b):
    out = subprocess.check_output([\"git\",\"diff\",\"--name-status\",f\"{a}..{b}\"], text=True)
    return [line.split(\"\\t\",1) for line in out.splitlines() if line]

def classify(path):
    if \"/delivery_control_001/\" in path:
        tail = path.split(\"/delivery_control_001/\",1)[1]
        return \"delivery_control/\" + (tail.split(\"/\",1)[0] if \"/\" in tail else \"root\")
    if \"/eval_audit_spine_001/\" in path:
        tail = path.split(\"/eval_audit_spine_001/\",1)[1]
        return \"eval_audit_spine/\" + (tail.split(\"/\",1)[0] if \"/\" in tail else \"root\")
    if \"/generator_v3_successor_001/v4_recovery/\" in path:
        tail = path.split(\"/v4_recovery/\",1)[1]
        return \"v4_recovery/\" + (tail.split(\"/\",1)[0] if \"/\" in tail else \"root\")
    if \"/checker/\" in path:
        return \"p7_checker\"
    if \"/contract/\" in path:
        return \"p7_upper_contract\"
    return \"p7_root_governance\"

for label,a,b in [(\"full_baseline_range\",base,candidate),(\"r4_delta\",r3,candidate)]:
    rows=changed(a,b)
    print(json.dumps({
        \"range\":label,
        \"file_count\":len(rows),
        \"status_counts\":dict(collections.Counter(status for status,_ in rows)),
        \"class_counts\":dict(sorted(collections.Counter(classify(path) for _,path in rows).items())),
        \"paths\":rows if label==\"r4_delta\" else None,
    }, ensure_ascii=False))
PY

